import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeAuthenticationsActionResultCodeSchema,
  type ResultCodeAuthenticationsActionResultCode,
} from "./result-code-authentications-action-result-code.js";
import { typeDisputesActionTypeSchema, type TypeDisputesActionType } from "./type-disputes-action-type.js";

export type Action24 = {
  /** A unique identifier generated by the platform to identify an action. */
  id?: string;
  /** Indicates the specific action taken. */
  type?: TypeDisputesActionType;
  /** Time indicating when the object was created in ISO-8601 format. */
  timeCreated?: Date;
  /** The result of the action executed. */
  resultCode?: ResultCodeAuthenticationsActionResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const action24Properties: s.Shape<Action24> = {
  id: s.optional(s.string()),
  type: s.optional(s.lazy(() => typeDisputesActionTypeSchema)),
  timeCreated: s.optional(s.dateTime()),
  resultCode: s.optional(s.lazy(() => resultCodeAuthenticationsActionResultCodeSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
    resultCode: "result_code",
    appId: "app_id",
    appName: "app_name",
  },
};

export const action24InternalSchema: Schema<Action24> = s.object<Action24>(action24Properties, {
  additionalProperties: s.json(),
});

export const action24Schema: Schema<Action24> = s.lazySchema(() =>
  s.object<Action24>(
    {
      ...action24Properties,
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
